use std::sync::Arc;
use credentials_backend::credential;
use credentials_backend::issuer::{CredentialRequest, Issuer};
use credentials_backend::notifier::{MemorySink, Notifier, WEBHOOK_KIND};
use credentials_backend::resolver::{did_key_for, did_web_url, Resolver};
use credentials_backend::settings::{Setting, SettingsStore};
use credentials_backend::status::{StatusChange, StatusList};
use credentials_backend::store::Store;
use credentials_backend::transport::StaticTransport;
use credentials_backend::verifier::{Submission, Verifier};
use credentials_backend::webhook::{Endpoint, HermeticTransport};
use ed25519_dalek::SigningKey;
use serde_json::json;

const HARBOUR: &str = "did:web:members.harbourclub.example";
const DOC: &str = include_str!("/tmp/cold-N17-train3/reference/infra/hosted-dids/members.harbourclub.example/.well-known/did.json");
fn seed(h: &str) -> [u8; 32] { let mut o=[0u8;32]; for i in 0..32 { o[i]=u8::from_str_radix(&h[2*i..2*i+2],16).unwrap(); } o }
fn now() -> i64 { std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs() as i64 }
fn door(store: Arc<Store>) -> Verifier {
    Verifier::new(Resolver::new(Arc::new(StaticTransport::default().with("https://members.harbourclub.example/.well-known/did.json", DOC))), store)
}
fn harbour_issue(store: &Store, holder: &str, ty: &str) -> credentials_backend::issuer::IssuedCredential {
    Issuer::new(HARBOUR, &format!("{HARBOUR}#key-1"), &seed("9f3688f6e8b93b0cfa3b11c28fbc25fe5440192ed82835e7fe3ab590f03f6c75"))
        .issue(store, &CredentialRequest { holder: holder.into(), credential_type: ty.into(), claims: vec![("member".into(), json!(true))], issued_at: now()-86400, not_before: None, expires_at: now()+86400*30 }).unwrap()
}

fn main() {
    // P1: forged credential, no issuer key, proof type the verifier does not check.
    let store = Arc::new(Store::from_onboarding_data().unwrap());
    let member = SigningKey::from_bytes(&[1; 32]);
    harbour_issue(&store, &did_key_for(&member.verifying_key()), "MembershipCredential"); // any real issuance creates Harbour's list
    let attacker = SigningKey::from_bytes(&[66; 32]);
    let attacker_did = did_key_for(&attacker.verifying_key());
    let forged = json!({ "id": "urn:uuid:forged", "issuer": HARBOUR, "type": ["VerifiableCredential","MembershipCredential"],
        "not_before": 0, "expires_at": 4102444800i64, "credentialSubject": { "id": attacker_did, "_sd": [] },
        "credentialStatus": { "statusListId": format!("{HARBOUR}#revocation"), "statusListIndex": 99_999 },
        "proof": { "type": "AnythingElse" } });
    let mut vp = json!({ "holder": attacker_did, "verifiableCredential": forged, "nonce": "n1", "domain": "door" });
    let frag = attacker_did.trim_start_matches("did:key:").to_string();
    credential::sign(&mut vp, &attacker, &format!("{attacker_did}#{frag}"), "authentication", now());
    println!("P1 forged Harbour credential at the door: {:?}", door(store.clone()).verify_presentation(&Submission { request_id: "f1".into(), presentation: vp }, "n1", "door").map(|v| v.credential.issuer));

    // P2: did:web URL construction.
    for d in ["did:web:127.0.0.1", "did:web:169.254.169.254:latest:meta-data", "did:web:10.0.0.5%3A8443", "did:web:issuer.example:a%3Fx=1", "did:web:issuer.example%23", "did:web:user%40evil.example"] {
        println!("P2 {d} -> {:?}", did_web_url(d));
    }

    // P3: status list last index.
    let mut list = StatusList::new(8);
    let last = (0..8).map(|_| list.allocate().unwrap()).last().unwrap();
    list.set(last, true);
    println!("P3 capacity 8: last allocated index {last}, revoked after set(true)? {}", list.is_set(last));

    // P4: a credential of another type opens the door.
    let store4 = Arc::new(Store::from_onboarding_data().unwrap());
    let guest = SigningKey::from_bytes(&[4; 32]);
    let gdid = did_key_for(&guest.verifying_key());
    let issued = harbour_issue(&store4, &gdid, "GuestPass");
    let mut vp4 = json!({ "holder": gdid, "verifiableCredential": issued.credential, "nonce": "n4", "domain": "door" });
    let gf = gdid.trim_start_matches("did:key:").to_string();
    credential::sign(&mut vp4, &guest, &format!("{gdid}#{gf}"), "authentication", now());
    println!("P4 GuestPass at the membership door: {:?}", door(store4).verify_presentation(&Submission { request_id: "g1".into(), presentation: vp4 }, "n4", "door").map(|v| v.credential.id.len() > 0));

    // P5: backend canonical numbers vs RFC 8785 (ES Number::toString).
    for n in [json!(1e-7), json!(1e21), json!(1.5e300), json!(0.1)] {
        println!("P5 canonicalize({n}) = {}", credential::canonicalize(&n));
    }

    // P6: a failing submission burns the request id for the genuine one.
    let store6 = Arc::new(Store::from_onboarding_data().unwrap());
    let m6 = SigningKey::from_bytes(&[6; 32]);
    let d6 = did_key_for(&m6.verifying_key());
    let i6 = harbour_issue(&store6, &d6, "MembershipCredential");
    let mut good = json!({ "holder": d6, "verifiableCredential": i6.credential, "nonce": "n6", "domain": "door" });
    let f6 = d6.trim_start_matches("did:key:").to_string();
    credential::sign(&mut good, &m6, &format!("{d6}#{f6}"), "authentication", now());
    let v6 = door(store6);
    println!("P6 garbage with req-7: {:?}", v6.verify_presentation(&Submission { request_id: "req-7".into(), presentation: json!({}) }, "n6", "door").err());
    println!("P6 genuine with req-7:  {:?}", v6.verify_presentation(&Submission { request_id: "req-7".into(), presentation: good }, "n6", "door").err());

    // P7/P8: notifier with a malformed webhook setting and a loopback subscriber.
    let rt = tokio::runtime::Builder::new_current_thread().enable_time().start_paused(true).build().unwrap();
    rt.block_on(async {
        let settings = Arc::new(SettingsStore::new());
        let transport = Arc::new(HermeticTransport::new());
        let sink = Arc::new(MemorySink::default());
        settings.put(Setting::new(HARBOUR, "webhook/rp-typo", WEBHOOK_KIND, json!({ "endpoint": "https://rp.example/hook" })));
        settings.put(Setting::new(HARBOUR, "webhook/rp-loopback", WEBHOOK_KIND, json!({ "url": "http://127.0.0.1/internal/admin" })));
        settings.put(Setting::new(HARBOUR, "webhook/rp-ok", WEBHOOK_KIND, json!({ "url": "https://rp-ok.example/hook" })));
        transport.route("https://rp-ok.example/hook", Endpoint::ok());
        let notifier = Notifier::new(settings, transport.clone(), sink.clone());
        notifier.notify(&StatusChange { credential_id: "urn:uuid:x".into(), issuer: HARBOUR.into(), status_list: "l".into(), status_index: 1, revoked: true }).await;
        let ids: Vec<String> = sink.events().iter().map(|e| format!("{}={:?}", e.subscription, e.outcome)).collect();
        println!("P7 events: {ids:?}; health green: {}", notifier.canary_healthy());
        println!("P8 loopback subscriber received: {}", transport.received("http://127.0.0.1/internal/admin").len());
    });
}
EOF
cd $P && CARGO_TARGET_DIR=$S/target-rp cargo run -q 2>&1 | tail -30

